cssCode:
.reveal-text {
  opacity: 0; color: #ffffff; font-size: 40px; font-family: sans-serif; 
  font-weight: bold; text-shadow: 0 0 10px rgba(255,255,255,0.5); 
  transform: translateY(30px); transition: all 1s ease-out;
}
.reveal-active {
  opacity: 1; transform: translateY(0); 
  text-shadow: 0 0 20px #00d2ff, 0 0 40px #00d2ff;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#000000;display:flex;flex-direction:column;align-items:center;';
c.innerHTML = `
  <div style="height: 100vh; display: flex; align-items: center; color: #555; font-family: sans-serif;">SCROLL DOWN ↓</div>
  <div class="reveal-text">MotionZync Premium</div>
  <div style="height: 100vh;"></div>
`;
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) { entry.target.classList.add('reveal-active'); }
    else { entry.target.classList.remove('reveal-active'); }
  });
});
document.querySelectorAll('.reveal-text').forEach(el => observer.observe(el));
